"use client";
import {CashierBankCloseAction} from './cashier-bank-close-action';
import type {BankCloseRequest} from '@/lib/cashier-bank-close-request';
import {CashierBankCloseHistory} from './cashier-bank-close-history';
import {downloadReport} from '@/lib/report-export';
import {useEffect,useRef,useState} from 'react';import {hotelClient,hotelRpc} from '@/lib/pilot';import type {HandoffScope} from '@/lib/cashier-handoff';import {bankBalanceInput,readBankClose,bankCloseMoney,bankCloseRows} from '@/lib/cashier-bank-close';
export function CashierBankCloseReview({scope,bank}:{scope:HandoffScope;bank:string}){
 const [draft,setDraft]=useState<Omit<BankCloseRequest,'id'|'bank'>|null>(null),[reopen,setReopen]=useState<string|null>(null),[reason,setReason]=useState(''),[historyVersion,setHistoryVersion]=useState(0);
 const [start,setStart]=useState(''),[end,setEnd]=useState(''),[opening,setOpening]=useState(''),[closing,setClosing]=useState(''),[result,setResult]=useState<ReturnType<typeof readBankClose>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 async function review(){if(lock.current)return;lock.current=true;setBusy(true);setResult(null);setDraft(null);setReopen(null);setError('');try{if(!start||!end||start>=end)throw Error('Choose a valid statement period.');const first=bankBalanceInput(opening),last=bankBalanceInput(closing);const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen reconciliation.');const raw=await hotelRpc<Record<string,unknown>>('review_bank_close',{p_tenant:scope.tenant,p_property:scope.property,p_bank:bank,p_start:start,p_end:end,p_opening:first,p_closing:last});const r=readBankClose(raw,scope,bank,start,end,first,last);const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen reconciliation.');if(alive.current){setResult(r);if(raw.all_entries_posted===true&&raw.statement_balances===true&&raw.ledger_balance_matches===true&&raw.ledger_opening_matches===true)setDraft({kind:'close',review:raw,close:null,reason:null})}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to review statement.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section><h3>Statement closing review</h3><p>Compare your entered statement with recorded accounting. This review does not finalize a bank close.</p><fieldset disabled={busy}>{[['Statement start',start,setStart,'date'],['Statement end (exclusive)',end,setEnd,'date'],['Opening statement balance',opening,setOpening,'text'],['Closing statement balance',closing,setClosing,'text']].map(([label,value,setter,type])=><label key={label as string}>{label as string}<input type={type as string} value={value as string} onChange={e=>{(setter as (v:string)=>void)(e.target.value);setResult(null);setDraft(null)}}/></label>)}<button type="button" onClick={()=>void review()}>Review statement balances</button></fieldset>{error&&<p role="alert">{error}</p>}{result&&<div role="status"><button type="button" onClick={()=>{try{downloadReport('bank-closing-review-'+bank+'-'+result.start+'-'+result.end,bankCloseRows(result))}catch(e){setError(e instanceof Error?e.message:'Unable to export review.')}}}>Export closing review CSV</button><p>Recorded ledger opening: {bankCloseMoney(result.ledgerOpening)}</p><p>Statement opening minus ledger: {bankCloseMoney(result.openingDifference)}</p><p>Statement arithmetic difference: {bankCloseMoney(result.statementDifference)}</p><p>Recorded bank ledger balance: {bankCloseMoney(result.ledgerBalance)}</p><p>Statement minus ledger: {bankCloseMoney(result.ledgerDifference)}</p><p>Statement amount not posted: {bankCloseMoney(result.unposted)}</p>{!result.configured&&<p>Configure bank ledger accounts before reconciliation.</p>}{result.shared&&<p>This ledger account is shared with another bank. Its balance cannot be attributed to this bank alone.</p>}<p>Review outstanding deposits, corrections and opening balances before closing.</p></div>}<CashierBankCloseHistory key={historyVersion} scope={scope} bank={bank} onReopen={id=>{setResult(null);setDraft(null);setReopen(id);setReason('')}}/>{reopen&&<label>Reason for reopening close {reopen}<input value={reason} maxLength={500} onChange={e=>{const text=e.target.value;setReason(text);setDraft(text.trim().length>=4?{kind:'reopen',review:null,close:reopen,reason:text.trim()}:null)}}/></label>}<CashierBankCloseAction scope={scope} bank={bank} draft={draft} onResolved={()=>{setResult(null);setDraft(null);setReopen(null);setReason('');setHistoryVersion(v=>v+1)}}/></section>
}
